// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertAll;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierStatisticsAvailability;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * Phase B review round, F1 (adopted from the reviewer's capacity scratch test): a read log never costs a family. On a
 * rotation of distinct queries without learning, through the public API with the store's default cache budget, the
 * cache with the read-log switch on holds at least as many families, serves at least as many {@code Use} decisions and
 * evicts no more than with the switch off: logs only occupy slack. The rotations are compared on equal terms: both run
 * after a discarded warm-up rotation, with no planner deadline (a planning cut by the wall clock under load is
 * published differently and would make the comparison a race between the two stores).
 *
 * <p>
 * The rotation has {@value #QUERIES} queries, which fit the default budget without their logs with room for about six
 * more families. The reviewer's rotation of 24 sits at the budget's edge: 22 to 24 of its families fit, varying from
 * run to run with the identity-deduplicated charges (which instances a template shares), and two stores then differ
 * whatever the switch, so its comparison is a measurement ({@value #QUERIES_PROPERTY}=24), not this test's assertion.
 */
@Timeout(1800)
class LmdbPlanCacheRevalidationCapacityTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "urn:revalidation-capacity:";
	private static final String PREFIX = "PREFIX ex: <" + NS + "> ";
	private static final int PEOPLE = 400;
	/** Queries in the asserted rotation. */
	private static final int QUERIES = 16;
	/** Measurement runs set another rotation size, such as the reviewer's 24. */
	private static final String QUERIES_PROPERTY = "rdf4j.test.revalidationCapacity.queries";

	@Test
	void readLogsNeverCostAFamilyOnARotationAtTheDefaultBudget(@TempDir Path directory) throws Exception {
		int queries = Integer.getInteger(QUERIES_PROPERTY, QUERIES);
		String previousTimeout = System.getProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY);
		System.setProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY, Long.toString(TimeUnit.MINUTES.toMillis(10)));
		Rotation off;
		Rotation on;
		try {
			rotate(true, directory.resolve("warm-up"), queries);
			off = rotate(false, directory.resolve("off"), queries);
			on = rotate(true, directory.resolve("on"), queries);
		} finally {
			if (previousTimeout == null) {
				System.clearProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY);
			} else {
				System.setProperty(LmdbCascadesOptimizer.TIMEOUT_MILLIS_PROPERTY, previousTimeout);
			}
		}
		System.out.println("[revalidation-capacity] queries=" + queries + " off=" + off);
		System.out.println("[revalidation-capacity] queries=" + queries + " on=" + on);

		assertAll(
				() -> assertTrue(off.families() > 0 && off.useOutcomes() > 0,
						"COVERAGE_PREREQUISITE: the rotation caches plans: " + off),
				() -> assertTrue(queries != QUERIES || off.families() == QUERIES,
						"COVERAGE_PREREQUISITE: the rotation fits the default budget with the switch off: " + off),
				() -> assertTrue(on.families() >= off.families(), "families: on=" + on + " off=" + off),
				() -> assertTrue(on.useOutcomes() >= off.useOutcomes(), "Use decisions: on=" + on + " off=" + off),
				() -> assertTrue(on.evictions() <= off.evictions(), "evictions: on=" + on + " off=" + off));
	}

	/**
	 * The cache after the rotation's four rounds without learning (what the assertions compare), then the outcome of
	 * one more round after one execution of each query (reported only: the learned state each store's replans read then
	 * depends on when its background maintenance published the executions' feedback).
	 */
	record Rotation(long families, long retainedBytes, long hits, long publications, long evictions,
			long useOutcomes, long useAfterLearning, long familiesAfterLearning, long evictionsAfterLearning,
			LmdbPlanCacheRevalidation.Snapshot revalidation) {
	}

	private static Rotation rotate(boolean validation, Path directory, int count) throws Exception {
		String previous = System.getProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY);
		System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, Boolean.toString(validation));
		List<String> queries = new ArrayList<>();
		for (int index = 0; index < count; index++) {
			// Distinct structures: each query joins a different number and choice of predicates.
			int a = index % 6;
			int b = (index / 6) % 4 + 6;
			queries.add("SELECT * WHERE { ?s ex:p" + a + " ?x . ?x ex:p" + b + " ?y . ?s ex:p" + ((a + 3) % 10)
					+ " ?z " + (index % 2 == 0 ? "FILTER(?z != ?y)" : "OPTIONAL { ?y ex:p" + ((b + 1) % 10) + " ?w }")
					+ " }");
		}
		LmdbStoreConfig config = new LmdbStoreConfig();
		config.setOptimizerSamplingEnabled(false);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.begin();
			for (int index = 0; index < PEOPLE; index++) {
				IRI person = VF.createIRI(NS + "person/" + index);
				for (int p = 0; p < 10; p++) {
					if ((index + p) % 3 != 0) {
						connection.add(person, VF.createIRI(NS + "p" + p),
								VF.createIRI(NS + "person/" + (index * (p + 1) + 1) % PEOPLE));
					}
				}
			}
			connection.commit();
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			LmdbTestUtil.awaitBackgroundMaintenance(store, 120, TimeUnit.SECONDS);
			LmdbEstimatorRuntime runtime = ((LmdbEvaluationStatistics) store.getSailStore()
					.getEvaluationStatistics()).estimatorRuntime();
			long useOutcomes = 0L;
			for (int round = 0; round < 4; round++) {
				for (String query : queries) {
					if ("USE".equals(outcome(connection, query))) {
						useOutcomes++;
					}
				}
			}
			LmdbPlanDecisionCache decisions = runtime.frontierSettings().pipelinePlanCache().decisionCacheForTest();
			LmdbPlanDecisionCache.Statistics withoutLearning = decisions.statistics();
			// One execution per query, then another rotation: learning in between.
			for (String query : queries) {
				try (TupleQueryResult result = connection.prepareTupleQuery(PREFIX + query).evaluate()) {
					while (result.hasNext()) {
						result.next();
					}
				}
			}
			LmdbTestUtil.awaitBackgroundMaintenance(store, 120, TimeUnit.SECONDS);
			long useAfterLearning = 0L;
			for (String query : queries) {
				if ("USE".equals(outcome(connection, query))) {
					useAfterLearning++;
				}
			}
			LmdbPlanDecisionCache.Statistics afterLearning = decisions.statistics();
			return new Rotation(withoutLearning.families(), withoutLearning.retainedBytes(), withoutLearning.hits(),
					withoutLearning.publications(), withoutLearning.evictions(), useOutcomes, useAfterLearning,
					afterLearning.families(), afterLearning.evictions(), afterLearning.revalidation());
		} finally {
			repository.shutDown();
			if (previous == null) {
				System.clearProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY);
			} else {
				System.setProperty(LmdbPlanCacheRevalidation.VALIDATION_PROPERTY, previous);
			}
		}
	}

	private static String outcome(SailRepositoryConnection connection, String query) {
		TupleExpr plan = (TupleExpr) connection.prepareTupleQuery(PREFIX + query)
				.explain(Explanation.Level.Optimized)
				.tupleExpr();
		return plan.getStringMetricPlanned("optimizer.planCacheLookupOutcome");
	}
}
